const input=$json??{}; const event=input.event??input;
const dealId=event.deal_id??event.dealId, leadId=event.lead_id??event.leadId, propertyId=event.property_id??event.propertyId;
const provider=String(event.provider??event.provider_name??'').trim();
const providerMessageId=String(event.provider_message_id??event.message_id??'').trim();
const status=String(event.status??event.delivery_status??'').toLowerCase();
const channel=String(event.channel??'sms').toLowerCase();
const dnc=Boolean(event.dnc??event.do_not_contact), blockers=Array.isArray(event.blockers)?event.blockers:[];
const baseKey=event.idempotency_key??[dealId,leadId,propertyId,'seller-followup'].filter(Boolean).join(':');
const callbackKey=String(event.callback_idempotency_key??(baseKey+':callback:'+providerMessageId)).trim();
let route='WF-349', decision='callback_received';
if(dnc){route='WF-126';decision='dnc_hard_stop';}
else if(blockers.length){route='WF-126';decision='blocked';}
else if(!dealId||!leadId||!propertyId||!baseKey){route='WF-354';decision='identity_or_idempotency_missing';}
else if(!provider||!providerMessageId){route='WF-348';decision='provider_receipt_identity_missing';}
else if(!callbackKey){route='WF-348';decision='callback_idempotency_missing';}
else if(['delivered','sent','accepted'].includes(status)){route='WF-349';decision='delivery_success';}
else if(['failed','bounced','rejected','undeliverable'].includes(status)){route='WF-350';decision='delivery_failure';}
else if(['inbound','reply','seller_response','received'].includes(status)||event.inbound_response){route='WF-342';decision='seller_response';}
else {route='WF-349';decision='callback_pending_classification';}
return [{json:{...event,workflow:'WF-355',decision,route,deal_id:dealId,lead_id:leadId,property_id:propertyId,provider,provider_message_id:providerMessageId,status,channel,idempotency_key:baseKey,callback_idempotency_key:callbackKey,audit_event:'provider_dispatch_delivery_receipt_reconciliation'}}];
